-- Exact-time reference candidate coverage for 2022 UTC; read-only aggregate.
SELECT CASE WHEN a.`dateTime` >= 1640995200 AND a.`dateTime` < 1643673600 THEN 1 WHEN a.`dateTime` >= 1643673600 AND a.`dateTime` < 1646092800 THEN 2 WHEN a.`dateTime` >= 1646092800 AND a.`dateTime` < 1648771200 THEN 3 WHEN a.`dateTime` >= 1648771200 AND a.`dateTime` < 1651363200 THEN 4 WHEN a.`dateTime` >= 1651363200 AND a.`dateTime` < 1654041600 THEN 5 WHEN a.`dateTime` >= 1654041600 AND a.`dateTime` < 1656633600 THEN 6 WHEN a.`dateTime` >= 1656633600 AND a.`dateTime` < 1659312000 THEN 7 WHEN a.`dateTime` >= 1659312000 AND a.`dateTime` < 1661990400 THEN 8 WHEN a.`dateTime` >= 1661990400 AND a.`dateTime` < 1664582400 THEN 9 WHEN a.`dateTime` >= 1664582400 AND a.`dateTime` < 1667260800 THEN 10 WHEN a.`dateTime` >= 1667260800 AND a.`dateTime` < 1669852800 THEN 11 WHEN a.`dateTime` >= 1669852800 AND a.`dateTime` < 1672531200 THEN 12 END AS month_utc, COUNT(*) AS archive_rows, SUM(a.`outHumidity` IS NULL) AS target_RH_null, SUM(a.`outHumidity` IS NOT NULL) AS target_RH_nonnull, SUM(o.`observed_at_utc` IS NOT NULL) AS exact_LuhaMet_timestamps, SUM(o.`relative_humidity_pct` IS NOT NULL) AS exact_LuhaMet_RH_values, SUM(a.`outHumidity` IS NOT NULL AND o.`relative_humidity_pct` IS NOT NULL) AS comparable_RH_pairs, AVG(a.`outHumidity`-o.`relative_humidity_pct`) AS target_minus_LuhaMet_bias_pct, AVG(ABS(a.`outHumidity`-o.`relative_humidity_pct`)) AS RH_MAE_pct, SQRT(AVG(POW(a.`outHumidity`-o.`relative_humidity_pct`,2))) AS RH_RMSE_pct FROM `loucka_reconstruction`.`archive` a LEFT JOIN `loucka_reconstruction`.`reference_observations` o ON o.`station_id`='luhamet_sehradice' AND o.`observed_at_utc`=a.`dateTime` WHERE a.`dateTime` >= 1640995200 AND a.`dateTime` < 1672531200 GROUP BY month_utc ORDER BY month_utc;
